static void detectNPlusOne(SessionFactory sf, Runnable op, long threshold) {
    long before = sf.getStatistics().getQueryExecutionCount();
    op.run();
    long after = sf.getStatistics().getQueryExecutionCount();
    if (after - before > threshold) System.out.println("OSTRZEZENIE: mozliwy N+1 (" + (after-before) + " zapytan)");
}

@NamedEntityGraph(name="Customer.deep",
    attributeNodes = @NamedAttributeNode(value="orders", subgraph="ordersSub"),
    subgraphs = @NamedSubgraph(name="ordersSub", attributeNodes = @NamedAttributeNode("items")))

static Customer load(Session s, Long id, String mode) {
    return "detailed".equals(mode) ? loadWithOrders(s, id) : s.find(Customer.class, id);
}

